    <section class="mt-6 rounded-2xl border border-stone-200 bg-white p-5"><h2 class="text-xl font-bold">Cierres y horarios excepcionales</h2><p class="mt-1 text-sm text-stone-600">Festivos, eventos privados o aperturas especiales. Sustituyen el horario semanal de esa fecha.</p><form wire:submit="saveClosure" class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><label><span class="mb-1 block font-medium">Fecha</span><input wire:model="closureDate" type="date" class="w-full rounded-xl border border-stone-300 px-3 py-2.5"></label><label class="flex items-center gap-2 pt-7"><input wire:model.live="closureIsClosed" type="checkbox"> Cerrado todo el día</label><label><span class="mb-1 block font-medium">Apertura</span><input wire:model="closureOpensAt" type="time" class="w-full rounded-xl border border-stone-300 px-3 py-2.5" @disabled($closureIsClosed)></label><label><span class="mb-1 block font-medium">Cierre</span><input wire:model="closureClosesAt" type="time" class="w-full rounded-xl border border-stone-300 px-3 py-2.5" @disabled($closureIsClosed)></label><label><span class="mb-1 block font-medium">Motivo</span><input wire:model="closureReason" class="w-full rounded-xl border border-stone-300 px-3 py-2.5"></label><button class="rounded-xl bg-stone-900 px-4 py-3 font-semibold text-white sm:col-span-2 lg:col-span-5">Guardar excepción</button></form><div class="mt-5 flex flex-wrap gap-2">@foreach($closures as $closure)<div class="flex items-center gap-3 rounded-xl border border-stone-200 px-3 py-2 text-sm"><span><strong>{{ $closure->date->format('d/m/Y') }}</strong> · {{ $closure->is_closed ? 'Cerrado' : substr($closure->opens_at,0,5).'–'.substr($closure->closes_at,0,5) }} {{ $closure->reason ? '· '.$closure->reason : '' }}</span><button wire:click="deleteClosure({{ $closure->id }})" wire:confirm="¿Eliminar esta excepción?" class="font-bold text-red-700">✕</button></div>@endforeach</div></section>
